and.sqlCheck:
/* operational-admission:constraint-enforcement */
SELECT CASE WHEN @@SESSION.foreign_key_checks = 1 AND @@SESSION.unique_checks = 1
    THEN 0 ELSE 1 END

/* operational-admission:delete-relationships-privilege */
SELECT CASE WHEN EXISTS (
    SELECT 1 FROM role WHERE role IN ('Admision', 'SIHSALUS Admision')
) AND (
    SELECT COUNT(*) FROM privilege
    WHERE HEX(privilege) = HEX('Delete Relationships')
) <> 1 THEN 1 ELSE 0 END

/* operational-admission:orphan-core-references */
SELECT (
    SELECT COUNT(*) FROM user_role u
    WHERE u.role IN ('Admision', 'SIHSALUS Admision')
      AND NOT EXISTS (SELECT 1 FROM role r WHERE r.role = u.role)
) + (
    SELECT COUNT(*) FROM role_privilege p
    WHERE p.role IN ('Admision', 'SIHSALUS Admision')
      AND NOT EXISTS (SELECT 1 FROM role r WHERE r.role = p.role)
)

changeSet.sql:
SELECT role FROM role
WHERE role IN ('Admision', 'SIHSALUS Admision')
FOR UPDATE;

SET @canonicalize_admission_alias = (SELECT COUNT(*) FROM role r WHERE HEX(r.role) = HEX('SIHSALUS Admision') AND (SELECT COUNT(*) FROM role_privilege p WHERE p.role = r.role) = 55);

INSERT INTO user_role (user_id, role)
SELECT legacy.user_id, 'Admision'
FROM user_role legacy
WHERE @canonicalize_admission_alias = 1 AND legacy.role = 'SIHSALUS Admision'
  AND NOT EXISTS (
    SELECT 1 FROM user_role canonical
    WHERE canonical.user_id = legacy.user_id AND canonical.role = 'Admision'
  );

SET @admission_optional_sql = IF(
    @canonicalize_admission_alias = 1 AND EXISTS (
        SELECT 1 FROM information_schema.TABLES
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'patientflags_tag_role'
    ),
    'INSERT INTO patientflags_tag_role (tag_id, role) SELECT DISTINCT legacy.tag_id, ''Admision'' FROM patientflags_tag_role legacy WHERE legacy.role = ''SIHSALUS Admision'' AND NOT EXISTS (SELECT 1 FROM patientflags_tag_role canonical WHERE canonical.tag_id = legacy.tag_id AND canonical.role = ''Admision'')',
    'SELECT 1'
);
PREPARE admission_optional_stmt FROM @admission_optional_sql;
EXECUTE admission_optional_stmt;
DEALLOCATE PREPARE admission_optional_stmt;

SET @admission_optional_sql = IF(
    @canonicalize_admission_alias = 1 AND EXISTS (
        SELECT 1 FROM information_schema.TABLES
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'stockmgmt_user_role_scope'
    ),
    'UPDATE stockmgmt_user_role_scope SET role = ''Admision'' WHERE role = ''SIHSALUS Admision''',
    'SELECT 1'
);
PREPARE admission_optional_stmt FROM @admission_optional_sql;
EXECUTE admission_optional_stmt;
DEALLOCATE PREPARE admission_optional_stmt;

SET @admission_optional_sql = IF(
    @canonicalize_admission_alias = 1 AND EXISTS (
        SELECT 1 FROM information_schema.TABLES
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'patientflags_tag_role'
    ),
    'DELETE FROM patientflags_tag_role WHERE role = ''SIHSALUS Admision''',
    'SELECT 1'
);
PREPARE admission_optional_stmt FROM @admission_optional_sql;
EXECUTE admission_optional_stmt;
DEALLOCATE PREPARE admission_optional_stmt;
SET @admission_optional_sql = NULL;

DELETE FROM user_role WHERE @canonicalize_admission_alias = 1 AND role = 'SIHSALUS Admision';
DELETE FROM role_privilege WHERE @canonicalize_admission_alias = 1 AND role = 'SIHSALUS Admision';
DELETE FROM role WHERE @canonicalize_admission_alias = 1 AND role = 'SIHSALUS Admision';

SET @canonicalize_admission_alias = NULL;

