changeSet.sql:
SELECT role FROM role
WHERE role IN ('Admision', 'SIHSALUS Admision')
FOR UPDATE;

INSERT INTO role (role, description, uuid)
SELECT 'Admision', legacy.description, UUID()
FROM role legacy
WHERE legacy.role = 'SIHSALUS Admision'
  AND NOT EXISTS (SELECT 1 FROM role canonical WHERE canonical.role = 'Admision');

INSERT INTO user_role (user_id, role)
SELECT legacy.user_id, 'Admision'
FROM user_role legacy
WHERE legacy.role = 'SIHSALUS Admision'
  AND NOT EXISTS (
    SELECT 1 FROM user_role canonical
    WHERE canonical.user_id = legacy.user_id AND canonical.role = 'Admision'
  );

INSERT INTO role_privilege (role, privilege)
SELECT 'Admision', legacy.privilege
FROM role_privilege legacy
WHERE legacy.role = 'SIHSALUS Admision'
  AND NOT EXISTS (
    SELECT 1 FROM role_privilege canonical
    WHERE canonical.role = 'Admision' AND canonical.privilege = legacy.privilege
  );

INSERT INTO role_privilege (role, privilege)
SELECT 'Admision', 'Delete Relationships'
FROM role canonical
WHERE canonical.role = 'Admision'
  AND NOT EXISTS (
    SELECT 1 FROM role_privilege existing_privilege
    WHERE existing_privilege.role = 'Admision'
      AND existing_privilege.privilege = 'Delete Relationships'
  );

